-- Shared pricing policy and read-only packaging evidence. No product prices,
-- stock, receipt records, approvals or outbound actions are changed here.
ALTER TABLE procurement_channel_products ADD COLUMN package_dimensions JSONB;
CREATE TABLE procurement_pricing_packages (
 variant_id BIGINT PRIMARY KEY REFERENCES product_variants(id) ON DELETE CASCADE,
 dimensions JSONB NOT NULL, observed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
